import React from 'react';

import { getCustomActionItems } from './get-custom-action-items.js';
import { TooltipItem } from '../../../types/tooltip.js';
import { TooltipActionTemplate } from '../../tooltip/shared/hooks/useTooltipSeriesActions.js';
import { getDefaultAction } from '../hooks/useDefaultAction.js';

const getActionsCallback = (actionsArray: React.JSX.Element[]) => {
  return () => <>{actionsArray}</>;
};

export const mergeTooltipActions = (
  tooltipItem?: TooltipItem,
  seriesActions?: TooltipActionTemplate,
) => {
  const defaultActionItem = getDefaultAction(tooltipItem);
  const customActionItems = getCustomActionItems(seriesActions, tooltipItem);
  const tooltipActions = [defaultActionItem, ...customActionItems];

  return getActionsCallback(tooltipActions);
};
